   522  static uint32_t
   523  string_decoder_getc_us_ascii(espeak_ng_TEXT_DECODER *decoder)
   524  {
   525          uint8_t c = *decoder->current++;
   526          return (c >= 0x80) ? 0xFFFD : c;
   527  }
   528
   529  static uint32_t
   530  string_decoder_getc_codepage(espeak_ng_TEXT_DECODER *decoder)
   531  {
   532          uint8_t c = *decoder->current++;
   533          return (c >= 0x80) ? decoder->codepage[c - 0x80] : c;
   534  }
   535
   536  static uint32_t
   537  string_decoder_getc_utf_8(espeak_ng_TEXT_DECODER *decoder)
   538  {
   539          uint8_t  c = *decoder->current++;
   540          uint32_t ret;
   541          switch (c & 0xF0)
   542          {
   543          // 1-byte UTF-8 sequence
   544          case 0x00: case 0x10: case 0x20: case 0x30:
   545          case 0x40: case 0x50: case 0x60: case 0x70:
   546                  return c;
   547          // UTF-8 tail byte -- invalid in isolation
   548          case 0x80: case 0x90: case 0xA0: case 0xB0:
   549                  return 0xFFFD;
   550          // 2-byte UTF-8 sequence
   551          case 0xC0: case 0xD0:
   552                  if (decoder->current + 1 >= decoder->end) goto eof;
   553                  ret = c & 0x1F;
   554                  if (((c = *decoder->current++) & LEADING_2_BITS) != UTF8_TAIL_BITS) goto error;
   555                  ret = (ret << 6) + (c & 0x3F);
   556                  return ret;
   557          // 3-byte UTF-8 sequence
   558          case 0xE0:
   559                  if (decoder->current + 2 >= decoder->end) goto eof;
   560                  ret = c & 0x0F;
   561                  if (((c = *decoder->current++) & LEADING_2_BITS) != UTF8_TAIL_BITS) goto error;
   562                  ret = (ret << 6) + (c & 0x3F);
   563                  if (((c = *decoder->current++) & LEADING_2_BITS) != UTF8_TAIL_BITS) goto error;
   564                  ret = (ret << 6) + (c & 0x3F);
   565                  return ret;
   566          // 4-byte UTF-8 sequence
   567          case 0xF0:
   568                  if (decoder->current + 3 >= decoder->end) goto eof;
   569                  ret = c & 0x0F;
   570                  if (((c = *decoder->current++) & LEADING_2_BITS) != UTF8_TAIL_BITS) goto error;
   571                  ret = (ret << 6) + (c & 0x3F);
   572                  if (((c = *decoder->current++) & LEADING_2_BITS) != UTF8_TAIL_BITS) goto error;
   573                  ret = (ret << 6) + (c & 0x3F);
   574                  if (((c = *decoder->current++) & LEADING_2_BITS) != UTF8_TAIL_BITS) goto error;
   575                  ret = (ret << 6) + (c & 0x3F);
   576                  return (ret <= 0x10FFFF) ? ret : 0xFFFD;
   577          }
   578  error:
   579          --decoder->current;
   580          return 0xFFFD;
   581  eof:
   582          decoder->current = decoder->end;
   583          return 0xFFFD;
   584  }
