   586  static uint32_t
   587  string_decoder_getc_iso_10646_ucs_2(espeak_ng_TEXT_DECODER *decoder)
   588  {
   589          if (decoder->current + 1 >= decoder->end) {
   590                  decoder->current = decoder->end;
   591                  return 0xFFFD;
   592          }
   593
   594          uint8_t c1 = *decoder->current++;
   595          uint8_t c2 = *decoder->current++;
   596          return c1 + (c2 << 8);
   597  }
