   607  static uint32_t
   608  string_decoder_getc_auto(espeak_ng_TEXT_DECODER *decoder)
   609  {
   610          const uint8_t *ptr = decoder->current;
   611          uint32_t c = string_decoder_getc_utf_8(decoder);
   612          if (c == 0xFFFD) {
   613                  decoder->get = string_decoder_getc_codepage;
   614                  decoder->current = ptr;
   615                  c = decoder->get(decoder);
   616          }
   617          return c;
   618  }
