   679  espeak_ng_STATUS
   680  text_decoder_decode_string(espeak_ng_TEXT_DECODER *decoder,
   681                             const char *string,
   682                             int length,
   683                             espeak_ng_ENCODING encoding)
   684  {
   685          if (encoding > ESPEAKNG_ENCODING_ISO_10646_UCS_2)
   686                  return ENS_UNKNOWN_TEXT_ENCODING;
   687
   688          const encoding_t *enc = string_decoders + encoding;
   689          if (enc->get == NULL)
   690                  return ENS_UNKNOWN_TEXT_ENCODING;
   691
   692          if (length < 0) length = string ? strlen(string) + 1 : 0;
   693
   694          decoder->get = string ? enc->get : null_decoder_getc;
   695          decoder->codepage = enc->codepage;
   696          decoder->current = (const uint8_t *)string;
   697          decoder->end = (const uint8_t *)(string ? string + length : string);
   698          return ENS_OK;
   699  }
