   737  espeak_ng_STATUS
   738  text_decoder_decode_string_multibyte(espeak_ng_TEXT_DECODER *decoder,
   739                                       const void *input,
   740                                       espeak_ng_ENCODING encoding,
   741                                       int flags)
   742  {
   743          switch (flags & 7)
   744          {
   745          case espeakCHARS_WCHAR:
   746                  return text_decoder_decode_wstring(decoder, (const wchar_t *)input, -1);
   747          case espeakCHARS_AUTO:
   748                  return text_decoder_decode_string_auto(decoder, (const char *)input, -1, encoding);
   749          case espeakCHARS_UTF8:
   750                  return text_decoder_decode_string(decoder, (const char *)input, -1, ESPEAKNG_ENCODING_UTF_8);
   751          case espeakCHARS_8BIT:
   752                  return text_decoder_decode_string(decoder, (const char *)input, -1, encoding);
   753          case espeakCHARS_16BIT:
   754                  return text_decoder_decode_string(decoder, (const char *)input, -1, ESPEAKNG_ENCODING_ISO_10646_UCS_2);
   755          default:
   756                  return ENS_UNKNOWN_TEXT_ENCODING;
   757          }
