   132  int is_str_totally_null(const char* str, int size) {
   133          // Tests if all bytes of str are null up to size
   134          // This should never be reimplemented with integers, because
   135          // this function has to work with unaligned char*
   136          // (casting to int when unaligned may result in ungaranteed behaviors)
   137          return (*str == 0 && memcmp(str, str+1, size-1) == 0);
